from pathlib import Path
import json,html,hashlib
R=Path('.'); products=json.loads((R/'assets/data/products.json').read_text(encoding='utf-8'))
e=html.escape
categories=[('refrigeration', 'Réfrigérateurs', 'Le froid au quotidien, dans tous les formats.', 'fa-temperature-low'), ('mini-bar', 'Mini-Bar', 'Le froid en format compact.', 'fa-cube'), ('congelation', 'Congélateurs', 'Des réserves bien conservées.', 'fa-snowflake'), ('lavage', 'Lave-linge', 'Du petit format aux grandes capacités.', 'fa-shirt'), ('eau', 'Fontaines à eau', 'Eau chaude, froide ou tempérée.', 'fa-droplet'), ('air', 'Rafraîchisseurs d’air', 'Plus de confort dans chaque pièce.', 'fa-wind')]
for p in products:
 p['subcategory']=(('top' if p['type']=='Lave-linge top' else 'semi-automatique') if p['category']=='lavage' else p.get('cooling','') if p['category']=='refrigeration' else '')
 p['capacityLabel']=(f"{p['capacity']} {p['unit']}" + (' nets' if p['category']=='refrigeration' and p['brand']!='White Whale' else '')) if p['capacity'] else ''
(R/'assets/data/products.json').write_text(json.dumps(products,ensure_ascii=False,indent=2),encoding='utf-8')
product_data='window.SMART_PRODUCTS = '+json.dumps(products,ensure_ascii=False)+';\n'
(R/'assets/js/products-data.js').write_text(product_data,encoding='utf-8')
product_version=hashlib.sha256(product_data.encode('utf-8')).hexdigest()[:12]
def gallery_arrow(direction):
 path='M15 6 9 12l6 6' if direction=='left' else 'm9 6 6 6-6 6'
 return f'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="{path}"/></svg>'

def card(p):
 badge=f'<span class="capacity-pill">{e(p["capacityLabel"])}</span>' if p['capacityLabel'] else ''
 visual=f'''<button class="product-card__img" data-detail="{p['id']}" aria-label="Voir {e(p['name'])}"><img src="{p['image']}" alt="{e(p['name'])}, {e(p['color'])}" loading="lazy" width="400" height="400">{badge}</button>'''
 if len(p.get('images',[]))>1:
  slides=''.join(f'<button type="button" class="gallery-slide" data-detail="{p['id']}" aria-label="Ouvrir la fiche de {e(p['model'])}"><img src="{src}" alt="{e(p.get("imageAlts",[p["model"]+" — vue extérieure",p["model"]+" — vue intérieure"])[i])}" loading="lazy" width="1086" height="1448"></button>' for i,src in enumerate(p['images']))
  visual=f'<div class="product-card__img gallery-frame" data-gallery aria-label="Photos du {e(p["model"])}"><div class="gallery-track" tabindex="0" aria-label="Faites défiler les photos">{slides}</div>{badge}<div class="gallery-controls"><button type="button" data-gallery-prev aria-label="Photo précédente">'+gallery_arrow('left')+f'</button><span class="gallery-position" aria-live="polite">1 / {len(p["images"])}</span><button type="button" data-gallery-next aria-label="Photo suivante">'+gallery_arrow('right')+'</button></div></div>'
 return f'''<article class="product-card" data-category="{p['category']}" data-subcategory="{p['subcategory']}" data-brand="{e(p['brand'])}" data-capacity="{p['capacity']}" data-search="{e(p['name']+' '+p['color']+' '+p['capacityLabel'])}" id="{p['id']}">
 {visual}

 <div class="product-card__body"><div class="product-card__brand">{e(p['brand'])}</div><p class="product-kind">{e(p['type'])}</p><h3 class="product-card__name">{e(p['model'])}</h3><p class="product-color">{e(p['color'])}</p><p class="product-excerpt">{e(p['description'])}</p>{'<p class="source-note">Informations à confirmer</p>' if p['note'] else ''}<button class="detail-button" data-detail="{p['id']}">Découvrir le produit <span aria-hidden="true"><svg class="ui-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></button></div></article>'''
def header(active):
 return f'''<header class="header"><div class="container header__inner"><a class="logo smart-logo" href="index.html" aria-label="SMART HOME GROUP — Accueil"><img class="brand-logo-image" src="assets/img/smart-home-logo.png" alt="SMART HOME Électroménager" width="526" height="133"></a><nav id="main-navigation" class="nav" aria-label="Navigation principale">{''.join(f'<a class="nav__link {"active" if active==file else ""}" href="{file}">{label}</a>' for file,label in [('index.html','Accueil'),('products.html','Nos produits'),('about.html','Notre univers'),('sav.html','SAV'),('contact.html','Contact')])}</nav><a href="products.html" class="header-catalogue">Explorer le catalogue <span aria-hidden="true"><svg class="ui-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a><button type="button" class="language-toggle" id="language-toggle" aria-label="Switch to English" lang="en">EN</button><button class="burger" aria-controls="main-navigation" aria-label="Ouvrir le menu" aria-expanded="false"><span></span><span></span><span></span></button></div></header>'''
footer='''<footer class="footer"><div class="container smart-footer"><div><a class="footer__brand footer-logo" href="index.html" aria-label="SMART HOME GROUP — Accueil"><img src="assets/img/smart-home-logo-transparent.png" alt="SMART HOME Électroménager" width="2170" height="725" loading="lazy"></a><p class="footer__desc">L’alliance du prix et de la qualité.<br>Électroménager pour votre quotidien.</p><a href="mailto:info@smarthome.com.tn">info@smarthome.com.tn</a></div><div><h2 class="footer__heading">Le catalogue</h2>'''+''.join(f'<a href="products.html?categorie={key}">{label}</a>' for key,label,_,_ in categories)+'''</div><div><h2 class="footer__heading">Nos marques</h2><p>FRESH · GÉANT · WHITE WHALE</p><a href="about.html">Notre univers</a><a href="sav.html">Service après-vente</a><a href="sav.html#reseau-distribution">Réseau de distribution</a><a href="contact.html">Nous contacter</a></div></div><div class="container footer__bottom"><span>© <span data-year></span> SMART HOME GROUP</span><span>Catalogue 2026</span></div></footer>'''
modal='''<dialog id="product-dialog" aria-labelledby="detail-title"><button class="dialog-close" aria-label="Fermer la fiche">✕</button><div class="detail-layout"><div class="detail-visual"><img id="detail-image" alt=""></div><div class="detail-content"><p id="detail-brand" class="eyebrow"></p><h2 id="detail-title"></h2><p id="detail-type"></p><div id="detail-tags" class="detail-tags"></div><h3>Description & caractéristiques</h3><p id="detail-description"></p><p id="detail-note" class="detail-note" hidden></p><a id="detail-contact" class="btn btn--primary" href="contact.html">Contacter notre équipe</a><p class="price-note">Prix et disponibilité sur demande.</p></div></div></dialog>'''
def page(file,title,content,desc):
 (R/file).write_text(f'''<!doctype html><html lang="fr" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | SMART HOME GROUP</title><meta name="description" content="{e(desc)}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="assets/css/styles.css"><link rel="stylesheet" href="assets/css/catalogue.css?v=catalogue-final-30"></head><body><a class="skip-link" href="#main">Aller au contenu</a>{header(file)}<main id="main">{content}</main>{footer}{modal}<script src="assets/js/products-data.js?v={product_version}"></script><script src="assets/js/main.js"></script><script src="assets/js/catalogue.js?v=catalogue-final-30"></script><script src="assets/js/i18n-data.js?v={product_version}"></script><script src="assets/js/i18n.js?v=1"></script></body></html>''',encoding='utf-8')
catcards=''.join(f'''<a class="family-card" href="products.html?categorie={key}"><span class="family-icon"><i class="fas {icon}" aria-hidden="true"></i></span><h3>{label}</h3><p>{sum(p['category']==key for p in products)} modèles</p><span class="family-arrow" aria-hidden="true"><svg class="ui-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></a>''' for key,label,_,icon in categories)
featured=[next(p for p in products if p['id']==id) for id in ['produit-01','produit-08','produit-25','produit-23','produit-12','produit-14','produit-16','produit-18']]
home='''<section class="smart-hero"><div class="container hero-layout"><div class="hero-copy"><p class="eyebrow">LA MAISON, TOUT SIMPLEMENT.</p><h1>Le bon équipement.<br><span>Le confort en plus.</span></h1><p class="hero-description">Prenez soin de votre linge, conservez vos aliments et profitez d’un intérieur plus agréable. Découvrez notre sélection d’électroménager Fresh, Géant et White Whale.</p><div class="hero-buttons"><a class="btn btn--primary" href="products.html">Découvrir nos produits <span aria-hidden="true"><svg class="ui-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></span></a><a class="hero-secondary" href="#familles">Choisir par catégorie</a></div><div class="hero-facts"><span><strong>{len(products)}</strong> modèles au catalogue</span><span><strong>6</strong> familles de produits</span><span><strong>3</strong> marques</span></div></div><div class="hero-visual hero-video-visual"><video id="hero-video" class="hero-video" autoplay muted loop playsinline disablepictureinpicture disableremoteplayback preload="metadata" poster="assets/img/catalogue/maison.webp" aria-label="Présentation animée des appareils SMART HOME GROUP"><source src="assets/video/smart-home-hero-v4.mp4" type="video/mp4"></video><div class="hero-caption"><img class="hero-brand-logo" src="assets/img/smart-home-logo.png" alt="SMART HOME Électroménager" width="526" height="133"><strong>L’alliance du prix<br>et de la qualité.</strong></div></div></div></section><section class="brand-strip"><div class="container"><span>DES MARQUES POUR VOTRE QUOTIDIEN</span><div class="partner-brands" aria-label="Nos marques"><strong class="brand-fresh">FRESH</strong><strong class="brand-geant">Géant<small>ELECTRONICS</small></strong><img class="brand-white-whale" src="assets/img/brands/white-whale-logo.png" alt="White Whale" width="2170" height="725" loading="lazy"></div><span class="catalogue-year">Collection 2026</span></div></section>'''
home=home.replace('{len(products)}',str(len(products)))
home+=f'''<section class="section" id="familles"><div class="container"><div class="section-heading"><div><p class="eyebrow">À CHAQUE BESOIN, SA SOLUTION</p><h2>Votre maison, bien équipée.</h2></div><p>Explorez nos six univers et trouvez <br>l’appareil adapté à votre quotidien.</p></div><div class="family-grid">{catcards}</div></div></section><section class="section selection-section"><div class="container"><div class="section-heading"><div><p class="eyebrow">LE CATALOGUE SMART HOME</p><h2>À découvrir.</h2></div><a class="text-link" href="products.html">Voir les {len(products)} produits <svg class="ui-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a></div><div class="products-grid">{''.join(card(p) for p in featured)}</div></div></section><section class="container home-callout"><div><p class="eyebrow">DU COMPACT AU GRAND FORMAT</p><h2>Un appareil à la mesure<br>de votre foyer.</h2><p>Comparez les capacités, les couleurs et les caractéristiques<br>pour faire votre choix.</p></div><a class="btn btn--primary" href="products.html">Explorer le catalogue <svg class="ui-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a></section>'''
home+='''<section class="container sav-home-banner"><div><p class="eyebrow">À VOS CÔTÉS APRÈS L’ACHAT</p><h2>Un service après-vente<br>présent en Tunisie.</h2><p>Nos techniciens internes et nos 18 agents agréés vous accompagnent pour vos appareils.</p></div><a class="btn btn--primary" href="sav.html">Découvrir notre SAV</a></section>'''
page('index.html' ,'Accueil',home,f'Découvrez les {len(products)} produits électroménagers Fresh, Géant et White Whale de SMART HOME GROUP : lavage, réfrigération, congélation, eau et confort de l’air.')
filters=''.join(f'<button class="filter-tab" data-filter="{key}" aria-pressed="false">{label}<span>{sum(p["category"]==key for p in products)}</span></button>' for key,label,_,_ in categories)
groups=''
for n,(key,label,subtitle,_) in enumerate(categories,1):
 group=sorted([p for p in products if p['category']==key],key=lambda p:(p['capacity'] or float('inf'),p['model']))
 if key in ('lavage','refrigeration'):
  grid=''
  subsections=[('semi-automatique','Semi-automatique'),('top','Top')] if key=='lavage' else [('defrost','Defrost'),('no-frost','No Frost')]
  for subkey,sublabel in subsections:
   subset=[p for p in group if p['subcategory']==subkey]
   grid+=f'<section class="laundry-section" data-product-section="{subkey}" aria-labelledby="subsection-{key}-{subkey}"><div class="laundry-heading"><h3 id="subsection-{key}-{subkey}">{sublabel}</h3><span class="laundry-count">{len(subset)} modèles</span></div><div class="products-grid">'+''.join(card(p) for p in subset)+'</div></section>'
 else:
  grid='<div class="products-grid">'+''.join(card(p) for p in group)+'</div>'
 groups+=f'''<section class="catalogue-group" data-group="{key}" aria-labelledby="heading-{key}"><div class="group-heading"><span class="group-number">0{n}</span><div><h2 id="heading-{key}">{label}</h2><p>{subtitle}</p></div><span class="group-count">{len(group)} modèles</span></div>{grid}</section>'''

content=f'''<section class="catalogue-intro"><div class="container"><p class="eyebrow">COLLECTION 2026 · FRESH · GÉANT · WHITE WHALE</p><h1>Le catalogue.</h1><p>L’électroménager adapté à votre quotidien.<br>Découvrez nos modèles et trouvez l’appareil qui vous correspond.</p></div></section><section class="catalogue-section"><div class="container"><div class="catalogue-tools"><div class="filter-bar" aria-label="Filtrer par famille"><button class="filter-tab active" data-filter="all" aria-pressed="true">Tous les produits<span>{len(products)}</span></button>{filters}</div><div class="search-row"><label class="search-field"><i class="fas fa-search" aria-hidden="true"></i><span class="sr-only">Rechercher un produit</span><input type="search" id="product-search" placeholder="Rechercher un modèle, une capacité, une couleur…"></label><label class="brand-select">Marque<select id="brand-filter"><option value="all">Toutes les marques</option><option>Fresh</option><option>Géant</option><option>White Whale</option></select></label><label class="sort-select">Trier<select id="product-sort"><option value="capacity">Capacité croissante</option><option value="capacity-desc">Capacité décroissante</option><option value="name">Nom du modèle</option></select></label></div><div class="results-row"><p id="result-count" role="status" aria-live="polite">{len(products)} produits</p><button id="reset-filters" class="text-link">Réinitialiser les filtres</button></div></div><p class="empty-state" id="empty-state" hidden>Aucun produit ne correspond à votre recherche. Essayez un autre modèle ou réinitialisez les filtres.</p>{groups}<p class="catalogue-footnote">Pour connaître les prix et la disponibilité des appareils, contactez notre équipe.</p></div></section>'''
page('products.html','Nos produits',content,f'Les {len(products)} produits du catalogue SMART HOME GROUP, classés par famille avec photos, descriptions, capacités et filtres par marque.')
page('about.html','Notre univers',f'''<section class="catalogue-intro"><div class="container"><p class="eyebrow">SMART HOME GROUP</p><h1>Le confort commence<br>à la maison.</h1><p>L’alliance du prix et de la qualité.</p></div></section><section class="section"><div class="container about-layout"><img src="assets/img/catalogue/maison.webp" alt="Univers électroménager SMART HOME GROUP" width="1000" height="666"><div><p class="eyebrow">NOTRE UNIVERS</p><h2>Des appareils pour<br>le quotidien.</h2><p>SMART HOME GROUP rassemble dans son catalogue 2026 des appareils Fresh, Géant et White Whale pour le lavage, la réfrigération, la congélation, l’eau et le rafraîchissement de l’air.</p><p>Les {len(products)} fiches vous permettent de découvrir les modèles, leurs couleurs et leurs caractéristiques avant de préparer votre demande.</p><a class="btn btn--primary" href="products.html">Découvrir le catalogue <svg class="ui-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a></div></div></section><section class="section"><div class="container family-grid">{catcards}</div></section>''','L’univers électroménager de SMART HOME GROUP et les marques Fresh, Géant et White Whale.')
